import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import Counter as C

def analyze(i,o):
    H=len(i); W=len(i[0]); OW=len(o[0])
    sep=W-OV if False else None
    seps=[s for s in range(W) if len({i[r][s] for r in range(H)})==1]
    # choose separator closest to middle that leaves >= OW cols on each side
    cand=[s for s in seps if s>=OW and W-s-1>=OW]
    sep=max(cand) if cand else (W-OV-1)
    cl=C(v for row in i for v in row[:sep]).most_common(1)[0][0]
    cr=C(v for row in i for v in range(sep+1,W)).most_common(1)[0][0]
    cb=C(v for row in o for v in row).most_common(1)[0][0]
    tab={}
    for r in range(H):
        for c in range(min(OW,sep)):
            tab.setdefault((i[r][c]==cl,i[r][sep+1+c]==cr),set()).add(o[r][c])
    return {'sep':sep,'cl':cl,'cr':cr,'cb':cb,'tab':tab,'H':H,'W':W,'OW':OW}

for name in [1,2,3,4]:
    info=analyze(G[f'Demo pair {name} input'],G[f'Demo pair {name} output'])
    print(name,'sep',info['sep'],'cl',info['cl'],'cr',info['cr'],'cb',info['cb'])
    for k,v in sorted(info['tab'].items()): print('   ',k,v)

